Register Health Facility Site.code:
// Create a site in a Resource Map collection.
// submitSite does not resolve references in the collection ID and resolves with
// the server response instead of state, so call it inside fn().
fn(async state => {
  const site = await submitSite(
    // 1) Collection ID (a plain value, not $.data...).
    state.data.collectionId,
    // 2) The site.
    {
      name: 'Mwanza Health Centre',
      lat: -2.5164,
      lng: 32.9175,
      // Field values keyed by field code.
      properties: {
        facility_type: 'Health Centre',
        beds: 24,
        phone: '+255700000000',
      },
    }
  )(state);
  return { ...state, data: site };
});

Submit Site From Survey.code:
// Map a survey submission to a new site.
// submitSite does not resolve references in the collection ID and resolves with
// the server response instead of state, so call it inside fn().
fn(async state => {
  const site = await submitSite(
    // 1) Collection ID, from the payload.
    state.data.collectionId,
    // 2) Site built from the submission.
    {
      name: state.data.water_point_name,
      lat: state.data.gps.latitude,
      lng: state.data.gps.longitude,
      properties: {
        functional: state.data.is_functional,
        source_type: state.data.source_type,
        last_visited: state.data.submission_date,
      },
    }
  )(state);
  return { ...state, data: site };
});

Submit Many Sites.code:
// Create one site per item in $.data.sites.
each(
  $.data.sites,
  // submitSite resolves with the server response, not state, so wrap it
  // in fn() and return state to keep the configuration for the next item.
  fn(async state => {
    await submitSite(
      // 1) Collection ID.
      '303',
      // 2) Site data for the current item.
      {
        name: state.data.name,
        lat: state.data.lat,
        lng: state.data.lng,
        properties: state.data.properties,
      }
    )(state);
    return state;
  })
);
